head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > oncustompaste]<br/>GridView 컴포넌트에서 사용자가 붙여넣기(Ctrl+V) 동작을 수행할 때 발생합니다.",
    "validation" : [
        "preventPaste 속성으로 붙여넣기(Ctrl+V)가 차단된 경우 oncustompaste 이벤트가 발생하지 않습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (preventPaste=true 고정 샘플)
//  - con 옵션 없음(고정). preventPaste=true 면 비편집 셀에 Ctrl+V 시 oncustompaste 미발생을 검증한다.
//  - (엔진: preventPaste 가드는 이벤트 발생 앞에서 차단되나, 편집모드 셀에서는 적용 안 됨 -> 단일 클릭(비편집) 상태로 확인)
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (가장 먼저 생성)
    //  - 트리거(Ctrl+V 붙여넣기)는 사용자 액션
    $c.gcm.createLabel('label="[전제] GridView 에 preventPaste=true 고정 (붙여넣기 차단).\n[절차] 복사 원본 (Ctrl+C) 영역의 값을 선택 후 Ctrl+C 로 복사 → 그리드 셀을 단일 클릭(선택)한 뒤 Ctrl+V.\n[확인] preventPaste=true 이므로 oncustompaste 핸들러 출력이 결과창에 나오지 않으면(미발생) 정상입니다. (편집모드(더블클릭)에서는 preventPaste 가 적용되지 않으니 비편집 셀에서 확인하세요.)"', '', 'label1');

    // 복사 원본 (Ctrl+C) textarea 기본값 설정 (inner text 불가 -> setValue)
    //  - 탭(\t)=Cell 구분, 줄바꿈(\n)=Row 구분 시연용 다중 셀 값 (붙여넣을 클립보드 소스)
    par_copySource.setValue("복사A\t복사B\n복사C\t복사D");

    // 조건 설정
    //  - preventPaste : true (붙여넣기 차단). 사용자가 비편집 셀에 Ctrl+V 해도 oncustompaste 미발생
    let properties = {
        dataList: "data:dlt_bind",
        preventPaste: "true"
    };

    let cList = $c.gcm.createCList(properties);

    // oncustompaste 이벤트 핸들러 부착 (preventPaste=true 라 정상 동작 시 미발생)
    let eList = $c.gcm.createEList(["oncustompaste"]);

    // dataList 생성 (기본 데이터 바인딩)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);
}



// oncustompaste : 사용자가 붙여넣기(Ctrl+V) 동작을 수행할 때 발생
//  - preventPaste=true 면 (비편집 셀에서) 붙여넣기 동작이 차단되어 이 핸들러가 호출되지 않음(미발생)
//  - 만약 출력이 나온다면 preventPaste 차단이 동작하지 않은 것
scwin.target1_oncustompaste = function (e) {
    // 발생 시 한 줄 출력 (표준 DOM 이벤트 객체 e 는 한 줄)
    wf_body_bottom.getObj("scwin").setReturnValue("oncustompaste 발생 e : " + e + " , e.type : " + e.type);
    return true;
};
